Investigate this Wazuh alert:

{
  "severity": "critical",
  "alert_title": "T1609 Container Administration Command — docker exec root shell chain detected",
  "docker_host": {
    "ip": "10.108.57.184",
    "hostname": "prod-docker-host-01",
    "agent_id": "ag-047",
    "inferred_role": "compromised Docker host — attacker has docker socket access"
  },
  "target_container": "corp-app-prod",
  "attack_progression": [
    {
      "step": 1,
      "phase": "Container enumeration",
      "technique": "T1609",
      "what_happened": "At 2027-09-10T08:14:22Z, auditd on prod-docker-host-01 (agent ag-047) recorded a write syscall to /var/run/docker.sock by process /usr/bin/docker under uid=1042. This uid does not correspond to any known CI/CD service account — it is an unrecognized user with docker group membership. The docker ps command was used to enumerate all running containers. Wazuh rule 92701 fired: 'docker exec into running container' with rule.mitre.id=T1609.",
      "first_seen": "2027-09-10T08:14:22Z"
    },
    {
      "step": 2,
      "phase": "Sensitive file access inside container",
      "technique": "T1609",
      "what_happened": "At 2027-09-10T08:16:55Z, auditd recorded /usr/bin/docker being used with exec -u 0 against corp-app-prod, executing cat /etc/shadow inside the container as root (uid=0). Wazuh rule 92702 fired: 'Sensitive file access inside container' with rule.mitre.id=T1609 and rule.level=15. The data.audit.command value captured the full command string including the container name and the sensitive file path.",
      "first_seen": "2027-09-10T08:16:55Z"
    },
    {
      "step": 3,
      "phase": "Outbound beacon from container",
      "technique": "T1609",
      "what_happened": "At 2027-09-10T08:19:40Z, Suricata observed an outbound HTTP GET from the container network namespace toward 10.108.57.184 on port 80 with URI /beacon. Simultaneously, auditd logged docker exec into corp-app-prod executing curl with the TARGET_HOST beacon URL. This is a command-and-control check-in pattern confirming the attacker is interactively directing commands inside the production container.",
      "first_seen": "2027-09-10T08:19:40Z"
    },
    {
      "step": 4,
      "phase": "Loot file drop — FIM detection",
      "technique": "T1609",
      "what_happened": "At 2027-09-10T08:20:15Z, Wazuh FIM detected a new file /tmp/docker_loot_20270910_081422.txt on prod-docker-host-01. The file matched pattern docker_loot_*.txt in /tmp. Wazuh rule 52103 fired: 'FIM: docker loot file in /tmp'. The file contains container inspect output and the exec timestamp, consistent with the attacker staging exfiltration artifacts.",
      "first_seen": "2027-09-10T08:20:15Z"
    }
  ],
  "wazuh_rules_fired": [
    {"rule_id": "92701", "description": "docker exec into running container", "level": 12, "mitre": "T1609"},
    {"rule_id": "92702", "description": "Sensitive file access inside container", "level": 15, "mitre": "T1609"},
    {"rule_id": "52103", "description": "FIM: docker loot file in /tmp", "level": 10, "mitre": "T1609"}
  ],
  "expected_verdict": "TP / critical",
  "time_window": {"start": "2027-09-10T08:14:22Z", "end": "2027-09-10T08:20:15Z"},
  "alert_count": 3
}
